import assert from "node:assert/strict";
import { default as __ns1_cumulativeStdNormalProbability } from "./src/cumulative_std_normal_probability.js";
import { default as __ns1_normalDistribution } from "./src/normal_distribution.js";
import { default as __ns1_standardNormalTable } from "./src/standard_normal_table.js";
import { default as __ns1_zScore } from "./src/z_score.js";
const ss = Object.freeze({ cumulativeStdNormalProbability: __ns1_cumulativeStdNormalProbability, normalDistribution: __ns1_normalDistribution, standardNormalTable: __ns1_standardNormalTable, zScore: __ns1_zScore });
{
{
{
// Start above zero: at x = 0 the check reduces to the previous
        // test, and the two sides share one computed error function value,
        // so the symmetry itself holds to floating-point rounding.
        for (let x = 0.25; x <= 8; x += 0.25) {
            const above = ss.normalDistribution(4 + x, 4, 2, true);
            const below = ss.normalDistribution(4 - x, 4, 2, true);
            assert.ok(Math.abs(above + below - 1) < 1e-12);
        }
}
}
}

